@startuml

class EBike {
}

class Frame {
  + material : string
}

class DriveSystem {
}

class Motor {}

class Controller {
  + state : ControllerState
}

abstract class ControllerVariant {}

class BasicController extends ControllerVariant {}

class AdvancedController extends ControllerVariant {
  + nextInspectionDate : date
}

class Battery {
  + storedEnergyWh : double
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" ControllerVariant
EBike "1" *-- "0..2" Wheel
DriveSystem "1" *-- "1" Motor
ControllerVariant "1" -- "0..1" Battery : controls
ControllerVariant "1" -- "1" DriveSystem : commands

@enduml

